def _get_factory(f, dicts, kwargs):
    factory = kwargs.pop('factory', dict)
    if kwargs:
        raise TypeError("{}() got an unexpected keyword argument "
                        "'{}'".format(f.__name__, kwargs.popitem()[0]))
    # Try to get type from first dict if available and it's a Mapping
    try:
        first_dict = dicts[0] if hasattr(dicts, '__getitem__') else next(iter(dicts))
    except (IndexError, StopIteration, TypeError):
        first_dict = None
    if first_dict is not None and isinstance(first_dict, Mapping):
        return type(first_dict)
    return factory

